<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {useAuth} from '../stores/auth'
import {service,dataMode} from '../services'
import {useTask,confirmAction,errorText} from '../composables/useData'
import type {Unit} from '../types/domain'
import PageHeader from '../components/PageHeader.vue'
import LoadState from '../components/LoadState.vue'
import PermissionSelector from '../components/PermissionSelector.vue'
import SafeMarkdown from '../components/SafeMarkdown.vue'
const auth=useAuth(),route=useRoute(),router=useRouter(),task=useTask(),loading=ref(true),error=ref(''),preview=ref(false),tags=ref(''),baseline=ref(''),saved=ref(false)
const draft=ref<Partial<Unit>>({title:'',content:'',category:'团队协作',tags:[],attachments:[],status:'draft',acl:[]})
const dirty=computed(()=>!!baseline.value&&JSON.stringify({...draft.value,tags:tags.value})!==baseline.value)
async function load(){loading.value=true;error.value='';try{if(route.params.id)draft.value=await service.getUnit(String(route.params.id));else if(route.query.gap){const gap=(await service.list('gaps')).find(g=>g.id===route.query.gap);if(!gap)throw new Error('关联知识缺口不存在');draft.value.title=gap.question;draft.value.content=`# ${gap.question}\n\n## 待补充的问题\n\n${gap.samples.map(s=>'- '+s).join('\n')}\n\n## 标准说明\n\n`}
 tags.value=draft.value.tags?.join('，')||'';baseline.value=JSON.stringify({...draft.value,tags:tags.value})}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function revalidate(){if(!route.params.id)return;loading.value=true;try{await service.getUnit(String(route.params.id))}catch(e){error.value=errorText(e)}finally{loading.value=false}}
onMounted(()=>{void load();window.addEventListener('focus',revalidate)})
onBeforeUnmount(()=>window.removeEventListener('focus',revalidate))
async function save(){await task.run(async()=>{const input={...draft.value,tags:tags.value.split(/[,，]/).map(t=>t.trim()).filter(Boolean),gapId:route.query.gap?String(route.query.gap):undefined};if(!auth.has('knowledge.permissions'))delete input.acl;const unit=await service.save('units',input);saved.value=true;await router.replace(unit.restricted?'/knowledge/units':`/knowledge/units/${unit.id}`)},'知识已保存')}
onBeforeRouteLeave(async()=>!auth.user||!auth.has(route.params.id?'knowledge.update':'knowledge.create')||!dirty.value||saved.value||await confirmAction('尚有未保存的内容，离开后将丢失这些修改。','离开编辑页'))
</script>
<template><PageHeader :title="route.params.id?'编辑知识':'新建知识'" :description="route.query.gap?'补充并保存后，将自动关联知识缺口。':'维护正文、标签、附件信息与数据授权。'"><button class="btn quiet" @click="router.back()">取消</button><button class="btn primary" form="knowledge-form" :disabled="task.busy.value||loading||!!error">{{task.busy.value?'正在保存…':'保存知识'}}</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"><form id="knowledge-form" @submit.prevent="save"><div class="editor-layout"><div class="stack"><section class="panel"><label class="field">知识标题<input v-model="draft.title" required maxlength="150" placeholder="给知识一个明确的标题"></label><div class="form-grid"><label class="field">分类<input v-model="draft.category" required maxlength="40" list="categories"><datalist id="categories"><option>人事制度</option><option>财务制度</option><option>产品研发</option><option>项目管理</option><option>团队协作</option><option>客户服务</option></datalist></label><label class="field">标签<input v-model="tags" maxlength="200" placeholder="多个标签用逗号分隔"></label></div></section><section class="panel"><div class="panel-head"><h2>知识正文</h2><button type="button" class="text-button" @click="preview=!preview">{{preview?'继续编辑':'预览 Markdown'}}</button></div><SafeMarkdown v-if="preview" :content="draft.content||'尚未填写正文。'"/><textarea v-show="!preview" v-model="draft.content" class="editor-content" aria-label="知识正文" required placeholder="使用 Markdown 编写清晰、可引用的知识…" style="width:100%" /></section><section class="panel"><h2>源附件</h2><p v-if="!draft.attachments?.length" class="small muted" style="margin-top:12px">当前为手动编写的知识。上传原始 PDF、Word 等文件请使用导入中心。</p><div v-for="(file,i) in draft.attachments" :key="i" class="attachment-row"><span class="break">{{file.name}}</span><button type="button" class="text-button danger" @click="draft.attachments?.splice(i,1)">移除关联</button></div><p v-if="dataMode==='demo'&&draft.attachments?.length" class="small faint" style="margin-top:12px">演示附件仅包含文件信息，不保存真实文件内容。</p></section></div><aside class="stack"><section class="panel"><h2>发布状态</h2><label class="field">状态<select v-model="draft.status"><option value="draft">草稿</option><option value="published">已发布</option></select></label><p class="small faint" style="margin-top:16px">已发布且获得授权的知识可参与问答检索。</p></section><section v-if="auth.has('knowledge.permissions')" class="panel"><h2 style="margin-bottom:20px">数据授权</h2><PermissionSelector v-model="draft.acl!" /></section><p v-if="task.error.value" class="notice error">{{task.error.value}}</p></aside></div></form></LoadState></template>
